"use client";

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";
import { cn } from "cn";
import { CheckIcon } from "lucide-react";
import { type FeedbackOption, useFeedback } from "@/components/ui/feedback";

function Checkbox({
  className,
  feedback,
  onCheckedChange,
  ...props
}: CheckboxPrimitive.Root.Props & { feedback?: FeedbackOption }) {
  const trigger = useFeedback(feedback);
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        "peer relative flex size-4 shrink-0 items-center justify-center rounded-[5px] border border-transparent bg-input/90 outline-none transition-shadow after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/30 disabled:cursor-not-allowed disabled:opacity-50 group-has-focus-visible/field-label:not-data-checked:border-transparent group-has-disabled/field:opacity-50 group-has-focus-visible/field-label:ring-0 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 aria-invalid:aria-checked:border-primary data-checked:border-primary data-checked:bg-primary data-checked:text-primary-foreground group-has-focus-visible/field-label:data-checked:border-primary dark:data-checked:bg-primary dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40",
        className,
      )}
      onCheckedChange={(checked, eventDetails) => {
        onCheckedChange?.(checked, eventDetails);
        trigger("selection", checked ? "toggle-on" : "toggle-off");
      }}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="grid place-content-center text-current transition-none [&>svg]:size-3.5"
      >
        <CheckIcon />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}

export { Checkbox };

"use client";

import {
  createContext,
  type ReactNode,
  use,
  useCallback,
  useEffect,
  useRef,
} from "react";
import { type HapticKind, haptic } from "@/lib/haptics";
import {
  createTickPlayer,
  type TickPlayer,
  type TickVariant,
} from "@/lib/tick-sound";

/**
 * Per-component feedback switch. `true` plays haptics and sound, `"haptic"` or
 * `"sound"` plays only that one, `false` stays silent, and leaving it unset
 * follows the nearest `FeedbackProvider`.
 */
export type FeedbackOption = boolean | "haptic" | "sound";

interface FeedbackSettings {
  haptics: boolean;
  sound: boolean;
}

// Silent unless asked: a FeedbackProvider or a `feedback` prop turns it on,
// so components never gain side effects their primitives do not have.
const FeedbackContext = createContext<FeedbackSettings>({
  haptics: false,
  sound: false,
});

function FeedbackProvider({
  haptics = false,
  sound = false,
  children,
}: Partial<FeedbackSettings> & { children?: ReactNode }) {
  return (
    <FeedbackContext value={{ haptics, sound }}>{children}</FeedbackContext>
  );
}

const SILENT: FeedbackSettings = { haptics: false, sound: false };

function resolveFeedback(
  option: FeedbackOption | undefined,
  defaults: FeedbackSettings,
): FeedbackSettings {
  if (option === undefined) return defaults;
  if (option === true) return { haptics: true, sound: true };
  if (option === "haptic") return { haptics: true, sound: false };
  if (option === "sound") return { haptics: false, sound: true };
  return SILENT;
}

/**
 * Resolves whether haptics and sound are on, for components such as WheelPicker
 * that voice themselves but still follow the shared `feedback` switch.
 */
function useFeedbackSettings(option?: FeedbackOption, { optIn = false } = {}) {
  const context = use(FeedbackContext);
  return resolveFeedback(option, optIn ? SILENT : context);
}

/**
 * Returns a stable `trigger(kind, sound)` for a component's feedback moments;
 * `sound: false` keeps it to haptics for components that voice themselves.
 * Pass `optIn` for controls such as Button that should stay silent unless the
 * caller sets `feedback` explicitly.
 */
function useFeedback(option?: FeedbackOption, { optIn = false } = {}) {
  const settings = useFeedbackSettings(option, { optIn });
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  // Players are created on the first sound so silent controls never touch
  // Web Audio, and each one releases its share of the page context on unmount.
  const players = useRef(new Map<TickVariant, TickPlayer>());
  useEffect(() => {
    const current = players.current;
    return () => {
      for (const player of current.values()) player.dispose();
      current.clear();
    };
  }, []);

  return useCallback((kind: HapticKind, sound: TickVariant | false = "tap") => {
    const { haptics, sound: soundOn } = settingsRef.current;
    if (haptics) haptic(kind);
    if (!soundOn || !sound) return;
    let player = players.current.get(sound);
    if (!player) {
      player = createTickPlayer(sound);
      players.current.set(sound, player);
    }
    player.play();
  }, []);
}

export { FeedbackProvider, useFeedback, useFeedbackSettings };

// Fires a short system haptic, modeled on UIKit's feedback generators.
// Android and other browsers with the Vibration API get a timed pattern.
// iOS Safari has no Vibration API, but since iOS 18 toggling an
// `<input type="checkbox" switch>` plays the system Taptic click; clicking a
// hidden label for one is the only way a web page can reach the Taptic Engine.
// Both paths only work inside a user gesture, and everything else is a no-op.

export type HapticKind =
  | "selection"
  | "light"
  | "medium"
  | "heavy"
  | "success"
  | "warning"
  | "error";

const PATTERNS: Record<HapticKind, number | number[]> = {
  selection: 6,
  light: 10,
  medium: 16,
  heavy: 24,
  success: [10, 70, 14],
  warning: [16, 90, 16],
  error: [14, 50, 14, 50, 20],
};

// The iOS switch click has a single strength, so notification kinds are told
// apart by how many clicks they play.
const PULSES: Record<HapticKind, number> = {
  selection: 1,
  light: 1,
  medium: 1,
  heavy: 1,
  success: 2,
  warning: 2,
  error: 3,
};

const PULSE_GAP = 70; // milliseconds between iOS clicks

let label: HTMLLabelElement | null = null;

function getSwitchLabel(): HTMLLabelElement {
  if (label?.isConnected) return label;
  label = document.createElement("label");
  label.ariaHidden = "true";
  label.style.cssText =
    "position:fixed;width:1px;height:1px;overflow:hidden;opacity:0;pointer-events:none;clip-path:inset(50%)";
  const input = document.createElement("input");
  input.type = "checkbox";
  input.tabIndex = -1;
  input.setAttribute("switch", "");
  label.append(input);
  document.body.append(label);
  return label;
}

function canVibrate(): boolean {
  return typeof navigator.vibrate === "function";
}

// Only touch devices without the Vibration API take the switch path, so
// desktop browsers never pay for the hidden element.
function canTapticSwitch(): boolean {
  return window.matchMedia("(pointer: coarse)").matches;
}

export function haptic(kind: HapticKind = "selection") {
  if (typeof window === "undefined") return;
  try {
    if (canVibrate()) {
      navigator.vibrate(PATTERNS[kind]);
      return;
    }
    if (!canTapticSwitch()) return;
    const target = getSwitchLabel();
    target.click();
    for (let i = 1; i < PULSES[kind]; i++) {
      window.setTimeout(() => target.click(), PULSE_GAP * i);
    }
  } catch {
    // Haptics are decoration; a blocked API must never break the interaction.
  }
}

